// Purpose: Redact and Classify Failure. Keep this deterministic and fail closed.
const e = $json.execution || {}, w = $json.workflow || {}, last = String(e.lastNodeExecuted || '');
const raw = String(e.error?.message || $json.error?.message || 'Unknown workflow failure'), redacted = raw.replace(/(password|token|authorization|secret|cookie|account|card)\s*[:=]\s*[^\s,;]+/gi, '$1:[REDACTED]').replace(/[A-Za-z0-9+/_=-]{32,}/g, '[REDACTED]').slice(0, 500), status = Number(e.error?.httpCode || e.error?.statusCode || 0), retryable = status === 429 || status >= 500 || /timeout|ECONNRESET|ENOTFOUND|temporar/i.test(raw);
const provider_code = /Outlook|OneDrive|Microsoft/i.test(last) ? 'MICROSOFT_GRAPH' : /Codex|Subscription Agent/i.test(last) ? 'CODEX_SUBSCRIPTION' : /Actual/i.test(last) ? 'ACTUAL_BUDGET' : /Cashback/i.test(last) ? 'CASHBACK_COMPANION' : /Finance Executions|n8n/i.test(last) ? 'N8N_API' : '';
return [{ json: { execution_id: String(e.id || ''), workflow_id: String(w.id || ''), workflow_name: String(w.name || '').slice(0, 200), workflow_code: String(w.financeWorkflowCode || ''), run_id: String(e.id || ''), provider_code, error_class: retryable ? 'TRANSIENT' : 'TERMINAL', error_message_redacted: redacted, first_seen_at: new Date().toISOString(), readback_verified: false } }];

// Purpose: Compare Failure Receipt Readback. Keep this deterministic and fail closed.
const expected = $('Redact and Classify Failure').first().json, observed = $json;
if (observed.execution_id !== expected.execution_id || observed.workflow_id !== expected.workflow_id || observed.error_class !== expected.error_class || observed.error_message_redacted !== expected.error_message_redacted)
    throw new Error('FAILURE_RECEIPT_READBACK_MISMATCH');
return [{ json: observed }];

// Purpose: Read Provider Circuit after Failure. Keep this deterministic and fail closed.
const failure = $('Redact and Classify Failure').first().json;
return [{ json: { provider_code: failure.provider_code, state: 'CLOSED', transient_failure_count: 0, last_error_class: '', opened_at: null, retry_after: null, readback_verified: false } }];

// Purpose: Build OPEN Provider Circuit. Keep this deterministic and fail closed.
const failure = $('Redact and Classify Failure').first().json, row = $json?.provider_code ? $json : {}, count = Math.min(12, Number(row.transient_failure_count || 0) + 1), seconds = Math.min(3600, 60 * (2 ** Math.min(count - 1, 6))), now = new Date();
return [{ json: { provider_code: failure.provider_code, state: 'OPEN', transient_failure_count: count, last_error_class: failure.error_class, opened_at: now.toISOString(), retry_after: new Date(now.getTime() + seconds * 1000).toISOString(), readback_verified: false, updated_at: now.toISOString() } }];

// Purpose: Verify OPEN Circuit Readback. Keep this deterministic and fail closed.
const e = $('Build OPEN Provider Circuit').first().json, o = $json;
if (o.provider_code !== e.provider_code || o.state !== 'OPEN' || Number(o.transient_failure_count) !== e.transient_failure_count || o.retry_after !== e.retry_after)
    throw new Error('PROVIDER_CIRCUIT_READBACK_MISMATCH');
return [{ json: o }];
